#define _POSIX_C_SOURCE 199309L
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pthread.h>

// Helper thread to generate a signal after a short delay
void *signal_sender(void *arg) {
    sleep(1); 
    printf("[Sender] Sending SIGUSR1 to PID %d\n", getpid());
    if (kill(getpid(), SIGUSR1) == -1) {
        perror("kill");
    }
    return NULL;
}

int main() {
    sigset_t set;
    siginfo_t info;
    int signum;
    pthread_t sender_tid;

    // 1. Define the set of signals to wait for
    sigemptyset(&set);
    sigaddset(&set, SIGUSR1);

    // 2. Block the signal in the main thread's mask
    if (pthread_sigmask(SIG_BLOCK, &set, NULL) != 0) {
        perror("pthread_sigmask");
        return EXIT_FAILURE;
    }
    printf("[Main] SIGUSR1 blocked. Starting sender thread.\n");

    // 3. Create thread to asynchronously send the signal
    if (pthread_create(&sender_tid, NULL, signal_sender, NULL) != 0) {
        perror("pthread_create");
        return EXIT_FAILURE;
    }

    // 4. Synchronously wait for the signal
    printf("[Main] Waiting for signal using sigwaitinfo...\n");
    signum = sigwaitinfo(&set, &info);

    if (signum == -1) {
        perror("sigwaitinfo");
        if (errno == EINTR) {
            fprintf(stderr, "Wait interrupted.\n");
        }
        return EXIT_FAILURE;
    }

    // 5. Process results
    printf("[Main] Signal received: %d (SIGUSR1)\n", signum);
    printf("[Main] Signal sender PID: %d\n", info.si_pid);

    pthread_join(sender_tid, NULL);
    return EXIT_SUCCESS;
}
